use crate::connection_geometry::ConnectionRegion;
use crate::resources::{BaseResource, ConnectionPoint, ConnectionSites};
use crate::structural_material::StructuralMaterial;
use serde::{Deserialize, Serialize};
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Placement{pub x:f64,pub y:f64,pub rotation_radians:f64}
#[derive(Serialize,Clone,Debug,PartialEq)]pub struct StructuralUnit{pub material:StructuralMaterial,pub placement:Placement}
impl StructuralUnit{pub fn new(resource_name:impl Into<String>,placement:Placement)->Self{Self{material:StructuralMaterial::single(resource_name),placement}}pub fn from_material(material:crate::resources::Material,placement:Placement)->Option<Self>{Some(Self{material:StructuralMaterial::from_material(material)?,placement})}pub fn resource_name(&self)->Option<&str>{let[(name,amount)]=self.material.constituents()else{return None};if self.material.internal_bonds().is_empty()&&(*amount-1.0).abs()<=f64::EPSILON{Some(name.as_str())}else{None}}pub fn properties(&self,catalog:&[BaseResource])->Option<crate::resources::ResourceProperties>{if !self.material.is_valid()||!self.material.resolves_in_catalog(catalog){return None}Some(self.material.weighted_properties(catalog))}pub fn connection_sites(&self,catalog:&[BaseResource])->Option<ConnectionSites>{self.material.connection_sites(catalog)}pub fn shape<'a>(&self,catalog:&'a[BaseResource])->Option<&'a crate::resources::Shape>{self.material.shape(catalog)}}
impl<'de>Deserialize<'de>for StructuralUnit{fn deserialize<D>(deserializer:D)->Result<Self,D::Error>where D:serde::Deserializer<'de>{#[derive(Deserialize)]struct Stored{material:Option<StructuralMaterial>,resource_name:Option<String>,placement:Placement}let s=Stored::deserialize(deserializer)?;let m=match s.material{Some(m)=>m,None=>StructuralMaterial::single(s.resource_name.ok_or_else(||serde::de::Error::custom("structural unit has no material"))?)};if !m.is_valid(){return Err(serde::de::Error::custom("invalid structural material"))}Ok(Self{material:m,placement:s.placement})}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq,Eq,Hash)]pub struct ConnectionSiteRef{pub unit_index:usize,pub point_index:usize}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub enum BondEndpoint{Corner{point_index:usize},Boundary{angle_radians:f64},Fluid{local_x:f64,local_y:f64}}
impl BondEndpoint{pub fn corner(point_index:usize)->Self{Self::Corner{point_index}}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Bond{pub unit_a:usize,pub point_a:usize,pub unit_b:usize,pub point_b:usize,pub strength:f64,#[serde(default)]pub bond_energy:f64,#[serde(default)]pub endpoint_a:Option<BondEndpoint>,#[serde(default)]pub endpoint_b:Option<BondEndpoint>}
impl Bond{pub fn endpoint_a(&self)->BondEndpoint{self.endpoint_a.unwrap_or(BondEndpoint::Corner{point_index:self.point_a})}pub fn endpoint_b(&self)->BondEndpoint{self.endpoint_b.unwrap_or(BondEndpoint::Corner{point_index:self.point_b})}pub fn touches(&self,u:usize,p:usize)->bool{(self.unit_a==u&&matches!(self.endpoint_a(),BondEndpoint::Corner{point_index}if point_index==p))||(self.unit_b==u&&matches!(self.endpoint_b(),BondEndpoint::Corner{point_index}if point_index==p))}pub fn has_same_identity(&self,o:&Bond)->bool{(self.unit_a==o.unit_a&&self.endpoint_a()==o.endpoint_a()&&self.unit_b==o.unit_b&&self.endpoint_b()==o.endpoint_b())||(self.unit_a==o.unit_b&&self.endpoint_a()==o.endpoint_b()&&self.unit_b==o.unit_a&&self.endpoint_b()==o.endpoint_a())}pub fn is_valid(&self,n:usize,count:impl Fn(usize)->Option<usize>)->bool{if self.unit_a>=n||self.unit_b>=n||!self.bond_energy.is_finite()||self.bond_energy<0.0{return false}fn valid_endpoint(e:BondEndpoint,count:Option<usize>)->bool{match e{BondEndpoint::Corner{point_index}=>count.is_some_and(|n|point_index<n),BondEndpoint::Boundary{angle_radians}=>angle_radians.is_finite(),BondEndpoint::Fluid{local_x,local_y}=>local_x.is_finite()&&local_y.is_finite()}}valid_endpoint(self.endpoint_a(),count(self.unit_a))&&valid_endpoint(self.endpoint_b(),count(self.unit_b))}}
#[derive(Serialize,Deserialize,Clone,Debug,Default)]pub struct OrganismStructure{pub units:Vec<StructuralUnit>,pub bonds:Vec<Bond>}
impl OrganismStructure{pub fn new()->Self{Self::default()}pub fn add_unit(&mut self,u:StructuralUnit)->usize{self.units.push(u);self.units.len()-1}pub(crate)fn push_bond_unchecked(&mut self,b:Bond)->usize{self.bonds.push(b);self.bonds.len()-1}pub fn is_valid_bond(&self,b:&Bond,c:&[BaseResource])->bool{if !b.is_valid(self.units.len(),|i|self.units.get(i).and_then(|u|u.connection_sites(c)).and_then(|s|match s{ConnectionSites::Corners(p)=>Some(p.len()),_=>None})){return false}let Some(a)=self.units[b.unit_a].properties(c)else{return false};let Some(d)=self.units[b.unit_b].properties(c)else{return false};let strength=crate::combine::bond_strength(a,d);strength.is_finite()&&(0.0..=1.0).contains(&strength)}pub fn connection_site(&self,s:ConnectionSiteRef,c:&[BaseResource])->Option<ConnectionPoint>{match self.units.get(s.unit_index)?.connection_sites(c)?{ConnectionSites::Corners(p)=>p.get(s.point_index).copied(),_=>None}}pub fn bond_endpoint_region(&self,u:usize,e:BondEndpoint,c:&[BaseResource])->Option<ConnectionRegion>{let unit=self.units.get(u)?;let sites=unit.connection_sites(c)?;match(e,sites){(BondEndpoint::Corner{point_index},ConnectionSites::Corners(points))=>{let p=*points.get(point_index)?;Some(ConnectionRegion::Corner(crate::connection_geometry::transform_connection_point(p,unit.placement.x,unit.placement.y,unit.placement.rotation_radians)))}(BondEndpoint::Boundary{angle_radians},ConnectionSites::Circumference{radius})=>{let p=ConnectionPoint{x:radius*angle_radians.cos(),y:radius*angle_radians.sin(),direction_radians:angle_radians};Some(ConnectionRegion::Boundary{center_x:unit.placement.x,center_y:unit.placement.y,radius}) .map(|r|{let _=p; r})}(BondEndpoint::Fluid{local_x,local_y},ConnectionSites::Undetermined)=>Some(ConnectionRegion::Fluid{center_x:unit.placement.x+local_x,center_y:unit.placement.y+local_y,effective_radius:unit.shape(c).map(|s|s.form.bounding_radius()).unwrap_or(0.0)}),_=>None}}pub fn available_connection_sites(&self,c:&[BaseResource])->Vec<ConnectionSiteRef>{let mut o=Vec::new();for i in 0..self.units.len(){let Some(ConnectionSites::Corners(p))=self.units[i].connection_sites(c)else{continue};for j in 0..p.len(){o.push(ConnectionSiteRef{unit_index:i,point_index:j})}}o}pub fn connected_components(&self)->Vec<Vec<usize>>{let mut a=vec![Vec::<usize>::new();self.units.len()];for b in &self.bonds{if b.unit_a<self.units.len()&&b.unit_b<self.units.len(){a[b.unit_a].push(b.unit_b);a[b.unit_b].push(b.unit_a)}}let mut v=vec![false;self.units.len()];let mut out=Vec::new();for st in 0..self.units.len(){if v[st]{continue}let mut q=vec![st];v[st]=true;let mut cc=Vec::new();while let Some(u)=q.pop(){cc.push(u);for &n in &a[u]{if !v[n]{v[n]=true;q.push(n)}}}cc.sort_unstable();out.push(cc)}out}pub fn component_connection_sites(&self,c:&[usize],cat:&[BaseResource])->Vec<ConnectionSiteRef>{let set:std::collections::HashSet<usize>=c.iter().copied().collect();self.available_connection_sites(cat).into_iter().filter(|s|set.contains(&s.unit_index)).collect()}pub fn connection_load(&self,u:usize,p:usize,_c:&[BaseResource])->f64{self.bonds.iter().filter(|b|b.touches(u,p)).map(|b|crate::combine::experimental_bond_strength(b.bond_energy)).sum()}pub fn connection_count(&self,u:usize,p:usize)->usize{self.bonds.iter().filter(|b|b.touches(u,p)).count()}pub fn break_bond(&mut self,i:usize)->Option<Bond>{if i<self.bonds.len(){Some(self.bonds.remove(i))}else{None}}pub fn break_matching_bond(&mut self,t:Bond)->Option<Bond>{let i=self.bonds.iter().position(|b|b.has_same_identity(&t))?;self.break_bond(i)}pub fn disconnect_point(&mut self,u:usize,p:usize)->Vec<Bond>{let mut o=Vec::new();let mut i=0;while i<self.bonds.len(){if self.bonds[i].touches(u,p){o.push(self.bonds.remove(i))}else{i+=1}}o}pub fn loaded_points(&self)->Vec<(usize,usize)>{let mut o=Vec::new();for b in &self.bonds{for p in[(b.unit_a,b.point_a),(b.unit_b,b.point_b)]{if !o.contains(&p){o.push(p)}}}o}}
pub fn formation_threshold(a:f64,b:f64,la:f64,lb:f64)->f64{let la=la.max(0.0);let lb=lb.max(0.0);((a+b)/2.0)*(1.0+la.sqrt()+lb.sqrt())}
#[cfg(test)]mod tests{use super::*;#[test]fn material_is_owned_by_unit(){let u=StructuralUnit::new("Carbon",Placement{x:0.0,y:0.0,rotation_radians:0.0});assert_eq!(u.material.constituents(),&[("Carbon".into(),1.0)])}#[test]fn composite_identity_is_preserved(){let m=crate::resources::Material{parts:vec![("Carbon".into(),1.0),("Hydrogen".into(),1.0)],internal_bonds:vec![crate::resources::InternalBond{part_a:0,part_b:1}]};let u=StructuralUnit::from_material(m.clone(),Placement{x:0.0,y:0.0,rotation_radians:0.0}).unwrap();assert_eq!(u.material.material(),&m);assert!(matches!(u.connection_sites(&crate::resources::default_catalog()),Some(ConnectionSites::Corners(_))))}#[test]fn connection_load_tracks_derived_bond_energy_strength(){let catalog=crate::resources::default_catalog();let mut structure=OrganismStructure::new();let a=structure.add_unit(StructuralUnit::new("Carbon",Placement{x:0.0,y:0.0,rotation_radians:0.0}));let b=structure.add_unit(StructuralUnit::new("Carbon",Placement{x:1.0,y:0.0,rotation_radians:0.0}));structure.push_bond_unchecked(Bond{unit_a:a,point_a:0,unit_b:b,point_b:0,strength:0.05,bond_energy:1.0,endpoint_a:None,endpoint_b:None});let expected=crate::combine::experimental_bond_strength(1.0);assert!((structure.connection_load(a,0,&catalog)-expected).abs()<1e-12);structure.bonds[0].strength=0.95;assert!((structure.connection_load(a,0,&catalog)-expected).abs()<1e-12)}#[test]fn continuous_endpoint_is_not_a_socket_index(){let catalog=crate::resources::default_catalog();let mut structure=OrganismStructure::new();let water=structure.add_unit(StructuralUnit::new("Water",Placement{x:0.0,y:0.0,rotation_radians:0.0}));let endpoint=BondEndpoint::Fluid{local_x:0.5,local_y:0.25};let region=structure.bond_endpoint_region(water,endpoint,&catalog).unwrap();assert!(matches!(region,ConnectionRegion::Fluid{..}))}}
